WITH valid_shipments AS (SELECT * FROM shipments WHERE order_id IN (23, 36, 39) AND carrier NOT IN ('Flash', 'DHL')), Summary AS (SELECT DATE_TRUNC('MONTH', shipped_date) AS shipped_month, ROUND((100 * SUM(CASE WHEN carrier = 'FedEx' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_fedex FROM valid_shipments GROUP BY DATE_TRUNC('MONTH', shipped_date)) SELECT * FROM Summary ORDER BY pct_fedex DESC, shipped_month LIMIT 10;
